import pathlib, sys, hashlib, subprocess
R = pathlib.Path('/home/user/controle-ia-travail')
D = R/'brouillons/barreau8-lecture-sondes-v1'
B4 = D/'prereg-lecture-sondes-barreau8-v1-brouillon4.md'
P = D/'prereg-lecture-sondes-barreau8-v1-brouillon5.md'
assert not P.exists()
def sha(p): return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
assert sha(B4) == '2306803543563e732e1ecbca8452e237810fa0bfc872e23b28d14acdcc589b7b'
CL4 = 'brouillons/barreau8-lecture-sondes-v1/contre-lecture-brouillon4-v1.md'
H4 = '79be6f7eec2534cb9b01cc20ecc3b8720fb21952965ee09912a979cff0a57c30'
assert sha(R/CL4) == H4
HF = sha(R/'src/controle_ia/premier_test_ia/figees.py')
t = B4.read_text(encoding='utf-8'); fautes = []
def r(a, b, n=1):
    global t
    c = t.count(a)
    if c != n: fautes.append((c, a[:90])); return
    t = t.replace(a, b)
def coupe(debut, fin, neuf):
    global t
    if t.count(debut) != 1 or fin not in t[t.index(debut)+len(debut):]:
        fautes.append(('coupe', debut[:70], fin[:50])); return
    i = t.index(debut); j = t.index(fin, i+len(debut))
    t = t[:i] + neuf + t[j:]

